use std::{fs,path::Path,io::Read,collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/scalar-layout215";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn median(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main(){let smoke_only=std::env::args().nth(1).as_deref()==Some("smoke");let r=Path::new(R);let jobs=read(r.join("jobs.json"));let mut rows=vec![];let mut observed=0;let mut off_records=0;let mut workers=BTreeSet::new();let mut accepted=0;
 for j in jobs.as_array().unwrap(){let smoke=j["smoke"]==true;if smoke_only&&!smoke{continue;}let name=j["name"].as_str().unwrap();let d=r.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"}));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);let out=fs::read_to_string(d.join("stdout.log")).unwrap();assert_eq!(hash(d.join("stdout.log")),e["stdout_sha256"]);let mut wall=vec![];let mut cpu=vec![];let mut gap=vec![];let mut ratios=vec![];let mut count=0;
 for l in out.lines().filter_map(|l|l.strip_prefix("PHASE ")){let v:Value=serde_json::from_str(l).unwrap();let c:Vec<u64>=serde_json::from_value(v["group_cpu"].clone()).unwrap();assert_eq!(c.len(),4);count+=1;if j["trace"]==false{assert_eq!(c,[0;4]);off_records+=1;continue;}let t:Vec<u64>=serde_json::from_value(v["events"].clone()).unwrap();assert!(t[11]>=t[10]&&t[10]>0);assert!(c[0]>0&&c[1]>=c[0]);assert!(c[2]>0&&c[2]<=j["workers"].as_u64().unwrap());assert_eq!(c[2],c[3]);workers.insert(c[2]);let w=(t[11]-t[10])as f64;let u=(c[1]-c[0])as f64;assert!(u<=w+10_000.,"{name}: cpu{u} >wall{w}");wall.push(w/1e6);cpu.push(u/1e6);gap.push((w-u)/1e6);ratios.push(u/w);observed+=1;
 }assert_eq!(count,j["rounds"].as_u64().unwrap());accepted+=1;
 if j["trace"]==true{rows.push(json!({"name":name,"smoke":smoke,"aligned32":j["aligned32"],"block":j["block"],"records":count,"wall_median_ms":median(wall),"CPU_median_ms":median(cpu),"wall_minus_CPU_median_ms":median(gap),"CPU_over_wall_median":median(ratios)}));}
 }
 let mut compare=vec![];if !smoke_only{assert_eq!(accepted,16);assert_eq!(observed,1508);assert_eq!(off_records,1508);for block in 0..3{let get=|b:bool|rows.iter().find(|r|r["smoke"]==false&&r["aligned32"]==b&&r["block"]==block).unwrap();let f=|b:bool,k:&str|get(b)[k].as_f64().unwrap();compare.push(json!({"block":block,"OFF":get(false),"ON":get(true),"ON_minus_OFF_wall_ms":f(true,"wall_median_ms")-f(false,"wall_median_ms"),"ON_minus_OFF_CPU_ms":f(true,"CPU_median_ms")-f(false,"CPU_median_ms"),"ON_minus_OFF_gap_ms":f(true,"wall_minus_CPU_median_ms")-f(false,"wall_minus_CPU_median_ms")}));}}
 let mut aggregate=BTreeMap::new();if !smoke_only{for b in[false,true]{let selected=rows.iter().filter(|r|r["smoke"]==false&&r["aligned32"]==b).collect::<Vec<_>>();let mut m=BTreeMap::new();for k in["wall_median_ms","CPU_median_ms","wall_minus_CPU_median_ms","CPU_over_wall_median"]{m.insert(k,median(selected.iter().map(|r|r[k].as_f64().unwrap()).collect()));}aggregate.insert(if b{"ON"}else{"OFF"},m);}}
 let result=json!({"pass":true,"diagnostic_only":true,"source_checked_by":"layout-audit","traced_records":observed,"trace_off_zero_records":off_records,"worker_tags":workers,"rows":rows,"paired_blocks":compare,"median_of_process_medians":aggregate,"no_adoption_claim":true});let output=r.join(if smoke_only{"cpu-smoke.json"}else{"cpu-result.json"});assert!(!output.exists());fs::write(output,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("CPUaudit PASS {observed}traced/{off_records}traceOFF; {accepted}processes");}
